    "roadmap.r1.title": "\u041F\u043E\u0447\u0430\u0442\u043E\u043A \u0440\u043E\u0437\u0440\u043E\u0431\u043A\u0438",
    "roadmap.r1.sub": "\u0406\u0434\u0435\u044F, \u043F\u0440\u043E\u0442\u043E\u0442\u0438\u043F \u0456 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u0456\u043D\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043A\u0442\u0443\u0440\u0438",
    "roadmap.r1.date": "\u041F\u043E\u0447\u0430\u0442\u043E\u043A 2025",
    "roadmap.r1.features": [
      "\u0424\u043E\u0440\u043C\u0443\u0432\u0430\u043D\u043D\u044F \u043A\u043E\u043D\u0446\u0435\u043F\u0446\u0456\u0457 \u0442\u0430 \u0432\u0438\u043C\u043E\u0433",
      "\u0412\u0438\u0431\u0456\u0440 \u0441\u0442\u0435\u043A\u0430: WebRTC, P2P, \u043A\u0440\u0438\u043F\u0442\u043E\u0433\u0440\u0430\u0444\u0456\u044F",
      "\u041F\u0435\u0440\u0448\u0456 \u043F\u0440\u043E\u0442\u043E\u0442\u0438\u043F\u0438 \u043E\u0431\u043C\u0456\u043D\u0443 \u043F\u043E\u0432\u0456\u0434\u043E\u043C\u043B\u0435\u043D\u043D\u044F\u043C\u0438",
      "\u0421\u0442\u0432\u043E\u0440\u0435\u043D\u043D\u044F \u0440\u0435\u043F\u043E\u0437\u0438\u0442\u043E\u0440\u0456\u044E \u0442\u0430 CI",
      "\u0411\u0430\u0437\u043E\u0432\u0430 \u0430\u0440\u0445\u0456\u0442\u0435\u043A\u0442\u0443\u0440\u0430 \u0448\u0438\u0444\u0440\u0443\u0432\u0430\u043D\u043D\u044F",
      "\u0414\u0438\u0437\u0430\u0439\u043D UX/UI"
    ],
    "roadmap.r2.title": "\u0410\u043B\u044C\u0444\u0430-\u0432\u0435\u0440\u0441\u0456\u044F",
    "roadmap.r2.sub": "\u041F\u0435\u0440\u0448\u0430 \u043F\u0443\u0431\u043B\u0456\u0447\u043D\u0430 \u0430\u043B\u044C\u0444\u0430: \u0431\u0430\u0437\u043E\u0432\u0438\u0439 \u0447\u0430\u0442 \u0456 \u043E\u0431\u043C\u0456\u043D \u043A\u043B\u044E\u0447\u0430\u043C\u0438",
