    "call.quality": "\u042F\u043A\u0456\u0441\u0442\u044C \u0437'\u0454\u0434\u043D\u0430\u043D\u043D\u044F",
    "call.qualityExcellent": "\u0412\u0456\u0434\u043C\u0456\u043D\u043D\u0430",
