    "group.new": "\u041D\u043E\u0432\u0430 \u0433\u0440\u0443\u043F\u0430",
    "group.create": "\u0421\u0442\u0432\u043E\u0440\u0438\u0442\u0438 \u0433\u0440\u0443\u043F\u0443",
    "group.join": "\u041F\u0440\u0438\u0454\u0434\u043D\u0430\u0442\u0438\u0441\u044F \u0434\u043E \u0433\u0440\u0443\u043F\u0438",
    "group.name": "\u041D\u0430\u0437\u0432\u0430 \u0433\u0440\u0443\u043F\u0438",
    "group.nameTooLong": "\u041D\u0430\u0437\u0432\u0430 \u0433\u0440\u0443\u043F\u0438 \u0437\u0430\u0434\u043E\u0432\u0433\u0430.",
    "group.capacity": "\u0414\u043E {max} \u043E\u0441\u0456\u0431, \u043D\u0430\u043F\u0440\u044F\u043C\u0443 \u043C\u0456\u0436 \u043F\u0440\u0438\u0441\u0442\u0440\u043E\u044F\u043C\u0438. \u0423\u0441\u0456 \u0437\u0432\u0456\u0440\u044F\u0442\u044C \u043E\u0434\u0438\u043D \u043A\u043E\u0434 \u0431\u0435\u0437\u043F\u0435\u043A\u0438, \u043F\u0435\u0440\u0448 \u043D\u0456\u0436 \u0433\u0440\u0443\u043F\u0430 \u0432\u0456\u0434\u043A\u0440\u0438\u0454\u0442\u044C\u0441\u044F.",
    "group.invite": "\u0417\u0430\u043F\u0440\u043E\u0441\u0438\u0442\u0438",
    "group.inviteMore": "\u0417\u0430\u043F\u0440\u043E\u0441\u0438\u0442\u0438 \u0449\u0435 \u0443\u0447\u0430\u0441\u043D\u0438\u043A\u0456\u0432",
    "group.invitePeople": "\u0417\u0430\u043F\u0440\u043E\u0441\u0438\u0442\u0438 {count} \u043E\u0441\u0456\u0431",
    "group.invitation": "\u0417\u0430\u043F\u0440\u043E\u0448\u0435\u043D\u043D\u044F \u0434\u043E \u0433\u0440\u0443\u043F\u0438",
    "group.addMembers": "\u0414\u043E\u0434\u0430\u0442\u0438 \u0443\u0447\u0430\u0441\u043D\u0438\u043A\u0456\u0432",
    "group.roomFor": "\u0404 \u043C\u0456\u0441\u0446\u0435 \u0449\u0435 \u0434\u043B\u044F {remaining}. \u041F\u0456\u0441\u043B\u044F \u043F\u0440\u0438\u0454\u0434\u043D\u0430\u043D\u043D\u044F \u0432\u0441\u0456 \u0437\u0432\u0456\u0440\u044F\u0442\u044C \u043D\u043E\u0432\u0438\u0439 \u043A\u043E\u0434 \u0433\u0440\u0443\u043F\u0438.",
    "group.membersCount": "{count} \u0443\u0447\u0430\u0441\u043D\u0438\u043A\u0456\u0432",
    "group.member": "\u0423\u0447\u0430\u0441\u043D\u0438\u043A",
    "group.members": "\u0423\u0447\u0430\u0441\u043D\u0438\u043A\u0438",
    "group.remove": "\u0412\u0438\u043B\u0443\u0447\u0438\u0442\u0438 {name}",
