    "group.leaveThis": "\u0412\u0438\u0439\u0442\u0438 \u0437 \u0446\u0456\u0454\u0457 \u0433\u0440\u0443\u043F\u0438",
    "group.cancel": "\u0421\u043A\u0430\u0441\u0443\u0432\u0430\u0442\u0438 \u0433\u0440\u0443\u043F\u0443",
    "group.close": "\u0417\u0430\u043A\u0440\u0438\u0442\u0438",
