    "desktop.chatCarriesCall": "\u0426\u0435\u0439 \u0447\u0430\u0442 \u043D\u0435\u0441\u0435 \u0433\u0440\u0443\u043F\u043E\u0432\u0438\u0439 \u0434\u0437\u0432\u0456\u043D\u043E\u043A. \u0412\u0438\u0439\u0434\u0456\u0442\u044C \u0456\u0437 \u0433\u0440\u0443\u043F\u043E\u0432\u043E\u0433\u043E \u0434\u0437\u0432\u0456\u043D\u043A\u0430, \u043F\u0435\u0440\u0448 \u043D\u0456\u0436 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0443\u0432\u0430\u0442\u0438 \u043E\u0434\u0438\u043D \u043D\u0430 \u043E\u0434\u0438\u043D.",
    "desktop.err.permission_denied": "\u0414\u0437\u0432\u0456\u043D\u043E\u043A \u043D\u0435 \u0432\u0434\u0430\u043B\u043E\u0441\u044F \u043F\u043E\u0447\u0430\u0442\u0438 - \u0434\u043E\u0441\u0442\u0443\u043F \u0434\u043E \u043C\u0456\u043A\u0440\u043E\u0444\u043E\u043D\u0430 \u0439 \u043A\u0430\u043C\u0435\u0440\u0438 \u0437\u0430\u0431\u043B\u043E\u043A\u043E\u0432\u0430\u043D\u043E. \u0414\u043E\u0437\u0432\u043E\u043B\u044C\u0442\u0435 \u0439\u043E\u0433\u043E \u0432 \u0441\u0438\u0441\u0442\u0435\u043C\u043D\u0438\u0445 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F\u0445 \u0456 \u0441\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u0449\u0435 \u0440\u0430\u0437.",
    "desktop.language": "\u041C\u043E\u0432\u0430",
    "desktop.languageHint": "\u0417\u0430\u0441\u0442\u043E\u0441\u043E\u0432\u0443\u0454\u0442\u044C\u0441\u044F \u043E\u0434\u0440\u0430\u0437\u0443. \u0423\u0436\u0435 \u043D\u0430\u0434\u0456\u0441\u043B\u0430\u043D\u0456 \u043F\u043E\u0432\u0456\u0434\u043E\u043C\u043B\u0435\u043D\u043D\u044F \u043B\u0438\u0448\u0430\u044E\u0442\u044C\u0441\u044F \u0442\u0456\u0454\u044E \u043C\u043E\u0432\u043E\u044E, \u044F\u043A\u043E\u044E \u0457\u0445 \u043D\u0430\u043F\u0438\u0441\u0430\u043B\u0438.",
    "desktop.compareCode": "\u041F\u043E\u0440\u0456\u0432\u043D\u044F\u0439\u0442\u0435 \u043A\u043E\u0434 \u043F\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043D\u043D\u044F \u0437\u0456 \u0441\u043F\u0456\u0432\u0440\u043E\u0437\u043C\u043E\u0432\u043D\u0438\u043A\u043E\u043C \u0456 \u043F\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u044C\u0442\u0435, \u044F\u043A\u0449\u043E \u0432\u0456\u043D \u0437\u0431\u0456\u0433\u0430\u0454\u0442\u044C\u0441\u044F.",
    "desktop.verifyBeforeFiles": "\u0417\u0430\u0432\u0435\u0440\u0448\u0456\u0442\u044C \u043F\u0435\u0440\u0435\u0432\u0456\u0440\u043A\u0443, \u043F\u0435\u0440\u0448 \u043D\u0456\u0436 \u043D\u0430\u0434\u0441\u0438\u043B\u0430\u0442\u0438 \u0444\u0430\u0439\u043B\u0438.",
    "desktop.verifyBeforeSending": "\u0417\u0430\u0432\u0435\u0440\u0448\u0456\u0442\u044C \u043F\u0435\u0440\u0435\u0432\u0456\u0440\u043A\u0443, \u043F\u0435\u0440\u0448 \u043D\u0456\u0436 \u043D\u0430\u0434\u0441\u0438\u043B\u0430\u0442\u0438 \u043F\u043E\u0432\u0456\u0434\u043E\u043C\u043B\u0435\u043D\u043D\u044F.",
    "desktop.disconnectedByBackend": "\u0417\u2019\u0454\u0434\u043D\u0430\u043D\u043D\u044F \u0431\u0435\u0437\u043F\u0435\u0447\u043D\u043E \u0440\u043E\u0437\u0456\u0440\u0432\u0430\u043D\u043E.",
