    "desktop.sec.integrityNa": "\u0421\u0430\u043C\u043E\u043F\u0435\u0440\u0435\u0432\u0456\u0440\u043A\u0443 \u0446\u0456\u043B\u0456\u0441\u043D\u043E\u0441\u0442\u0456 \u0432\u0438\u043A\u043E\u043D\u0430\u0442\u0438 \u043D\u0435 \u0432\u0434\u0430\u043B\u043E\u0441\u044F",
