    "desktop.sec.replayOk": "\u041A\u043B\u044E\u0447\u0456 \u043F\u043E\u0432\u0456\u0434\u043E\u043C\u043B\u0435\u043D\u044C \u0440\u0430\u0442\u0447\u0435\u0442\u0430 \u0437\u043D\u0438\u0449\u0443\u044E\u0442\u044C\u0441\u044F \u043F\u0456\u0441\u043B\u044F \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u0430\u043D\u043D\u044F, \u0442\u043E\u0436 \u043F\u0435\u0440\u0435\u0445\u043E\u043F\u043B\u0435\u043D\u0438\u0439 \u043A\u0430\u0434\u0440 \u043D\u0435 \u043C\u043E\u0436\u043D\u0430 \u0432\u0456\u0434\u0442\u0432\u043E\u0440\u0438\u0442\u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E",
    "desktop.sec.replayNa": "\u041D\u0435 \u0432\u0438\u043C\u0456\u0440\u044F\u043D\u043E",
    "desktop.sec.dtlsPinned": "\u0412\u0456\u0434\u0431\u0438\u0442\u043E\u043A DTLS \u0441\u043F\u0456\u0432\u0440\u043E\u0437\u043C\u043E\u0432\u043D\u0438\u043A\u0430 \u0437\u0430\u043A\u0440\u0456\u043F\u043B\u0435\u043D\u043E: {fp}",
