    "qr.scanning": "\u0421\u043A\u0430\u043D\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0435\u2026",
    "qr.hint": "\u0414\u0435\u0440\u0436\u0438\u0442\u0435 \u0440\u043E\u0432\u043D\u043E, \u043F\u043E\u043A\u0430 \u043D\u0435 \u0441\u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F \u0432\u0441\u0435 \u0447\u0430\u0441\u0442\u0438. \u041A\u0430\u043C\u0435\u0440\u0430 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u043E - \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F.",
    "mesh.you": "\u0432\u044B",
    "mesh.peer": "\u0441\u043E\u0431\u0435\u0441\u0435\u0434\u043D\u0438\u043A \xB7 \u0441\u0435\u0430\u043D\u0441 1",
    "mesh.joined2": "\u043B\u0435\u043D\u0430 \u043F\u0440\u0438\u0441\u043E\u0435\u0434\u0438\u043D\u0438\u043B\u0430\u0441\u044C \xB7 +2",
    "mesh.joined3": "\u043C\u0438\u0448\u0430 \u043F\u0440\u0438\u0441\u043E\u0435\u0434\u0438\u043D\u0438\u043B\u0441\u044F \xB7 +3",
    "ice.title": "\u0421\u0435\u0442\u0435\u0432\u044B\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438",
    "ice.subtitle": "\u041D\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u043E - \u043D\u0438\u043A\u043E\u0433\u0434\u0430 \u043D\u0435 \u043F\u0435\u0440\u0435\u0434\u0430\u0451\u0442\u0441\u044F \u0441\u043E\u0431\u0435\u0441\u0435\u0434\u043D\u0438\u043A\u0443",
    "ice.intro": "\u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E SecureBit \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u043F\u0443\u0431\u043B\u0438\u0447\u043D\u044B\u0435 STUN-\u0441\u0435\u0440\u0432\u0435\u0440\u044B, \u0447\u0442\u043E\u0431\u044B \u0441\u043E\u0433\u043B\u0430\u0441\u043E\u0432\u0430\u0442\u044C \u043F\u0440\u044F\u043C\u043E\u0435 \u0441\u043E\u0435\u0434\u0438\u043D\u0435\u043D\u0438\u0435. \u0415\u0441\u043B\u0438 \u0434\u0435\u0440\u0436\u0438\u0442\u0435 \u0441\u0432\u043E\u0438, \u0443\u043A\u0430\u0436\u0438\u0442\u0435 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0435 STUN/TURN.",
    "ice.publicTitle": "\u041F\u0443\u0431\u043B\u0438\u0447\u043D\u044B\u0435 \u0441\u0435\u0440\u0432\u0435\u0440\u044B (\u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E)",
    "ice.publicDesc": "\u0411\u0435\u0437 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438. \u041F\u043E\u0434\u0445\u043E\u0434\u0438\u0442 \u0431\u043E\u043B\u044C\u0448\u0438\u043D\u0441\u0442\u0432\u0443.",
    "ice.customTitle": "\u0421\u0432\u043E\u0438 STUN/TURN-\u0441\u0435\u0440\u0432\u0435\u0440\u044B",
    "ice.customDesc": "\u0414\u043E {max} \u0441\u0435\u0440\u0432\u0435\u0440\u043E\u0432.",
    "ice.turnNote": "TURN-relay \u0432\u0438\u0434\u0438\u0442 IP \u043E\u0431\u0435\u0438\u0445 \u0441\u0442\u043E\u0440\u043E\u043D \u0438 \u0440\u0438\u0442\u043C \u0442\u0440\u0430\u0444\u0438\u043A\u0430 - \u043D\u043E \u043D\u0438\u043A\u043E\u0433\u0434\u0430 \u0441\u043E\u0434\u0435\u0440\u0436\u0438\u043C\u043E\u0435 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0439, \u043A\u043E\u0442\u043E\u0440\u043E\u0435 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0437\u0430\u0448\u0438\u0444\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u043C \u0441\u043A\u0432\u043E\u0437\u043D\u044B\u043C \u043E\u0431\u0440\u0430\u0437\u043E\u043C. \u041B\u0443\u0447\u0448\u0435 ",
    "ice.turnNoteTls": " (TLS).",
    "ice.test": "\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u0441\u0435\u0440\u0432\u0435\u0440\u044B",
    "ice.testing": "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430\u2026",
    "ice.relayTitle": "\u0420\u0435\u0436\u0438\u043C \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0435\u0440\u0435\u0437 relay",
    "ice.relayBadge": "\u041C\u0410\u041A\u0421\u0418\u041C\u0423\u041C \u041F\u0420\u0418\u0412\u0410\u0422\u041D\u041E\u0421\u0422\u0418",
    "ice.relayDesc": "\u041F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u0435\u0442 \u0432\u0435\u0441\u044C \u0442\u0440\u0430\u0444\u0438\u043A \u0447\u0435\u0440\u0435\u0437 TURN, \u0442\u0430\u043A \u0447\u0442\u043E \u0441\u043E\u0431\u0435\u0441\u0435\u0434\u043D\u0438\u043A \u043D\u0438\u043A\u043E\u0433\u0434\u0430 \u043D\u0435 \u0443\u0432\u0438\u0434\u0438\u0442 \u0432\u0430\u0448\u0435\u0433\u043E IP. \u041D\u0443\u0436\u0435\u043D TURN-\u0441\u0435\u0440\u0432\u0435\u0440.",
    "ice.relayWarning": "\u0420\u0435\u0436\u0438\u043C \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0435\u0440\u0435\u0437 relay \u0432\u043A\u043B\u044E\u0447\u0451\u043D, \u043D\u043E TURN-\u0441\u0435\u0440\u0432\u0435\u0440 \u043D\u0435 \u0443\u043A\u0430\u0437\u0430\u043D. \u0421\u043E\u0435\u0434\u0438\u043D\u0435\u043D\u0438\u0435 \u043D\u0435 \u0441\u043C\u043E\u0436\u0435\u0442 \u043D\u0430\u0447\u0430\u0442\u044C\u0441\u044F.",
    "ice.persist": "\u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u043D\u0430 \u044D\u0442\u043E\u043C \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0435",
    "ice.persistDesc": "\u0425\u0440\u0430\u043D\u0438\u0442\u0441\u044F \u0437\u0430\u0448\u0438\u0444\u0440\u043E\u0432\u0430\u043D\u043D\u043E \u0432 \u044D\u0442\u043E\u043C \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0435. \u041E\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D\u043D\u044B\u043C, \u0447\u0442\u043E\u0431\u044B \u0434\u0435\u0439\u0441\u0442\u0432\u043E\u0432\u0430\u043B\u043E \u0442\u043E\u043B\u044C\u043A\u043E \u0432 \u044D\u0442\u043E\u043C \u0441\u0435\u0430\u043D\u0441\u0435.",
    "ice.forget": "\u0417\u0430\u0431\u044B\u0442\u044C \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u043E\u0435",
