    "offline.lostTitle": "\uC5F0\uACB0\uC774 \uB04A\uC5B4\uC84C\uC2B5\uB2C8\uB2E4",
    "offline.lostDesc": "SecureBit\uC774 \uC624\uD504\uB77C\uC778 \uC0C1\uD0DC\uC785\uB2C8\uB2E4. \uC77C\uBD80 \uAE30\uB2A5\uC774 \uC81C\uD55C\uB418\uC9C0\uB9CC \uB370\uC774\uD130\uB294 \uC548\uC804\uD569\uB2C8\uB2E4.",
    "offline.point1": "\uC138\uC158\uACFC \uD0A4\uB294 \uADF8\uB300\uB85C \uC720\uC9C0\uB429\uB2C8\uB2E4",
    "offline.point2": "\uC11C\uBC84\uC5D0\uB294 \uC544\uBB34 \uB370\uC774\uD130\uB3C4 \uC800\uC7A5\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4",
    "offline.point3": "\uB2E4\uC2DC \uC5F0\uACB0\uB418\uBA74 \uBA54\uC2DC\uC9C0\uC640 \uD30C\uC77C\uC774 \uB3D9\uAE30\uD654\uB429\uB2C8\uB2E4",
    "offline.continue": "\uC624\uD504\uB77C\uC778\uC73C\uB85C \uACC4\uC18D",
    "offline.restoredTitle": "\uB2E4\uC2DC \uC5F0\uACB0\uB418\uBA74",
    "offline.restoredDesc": "\uC5F0\uACB0\uC774 \uB04A\uACA8\uB3C4 \uC783\uB294 \uAC83\uC740 \uC5C6\uC2B5\uB2C8\uB2E4. SecureBit\uC740 \uBAA8\uB4E0 \uAC83\uC744 \uAE30\uAE30 \uC548\uC5D0 \uB300\uAE30\uC2DC\uCF1C \uB450\uC5C8\uB2E4\uAC00, \uB2E4\uC2DC \uC628\uB77C\uC778\uC774 \uB418\uB294 \uC989\uC2DC \uC554\uD638\uD654\uB41C \uC138\uC158\uC744 \uC774\uC5B4\uAC11\uB2C8\uB2E4.",
    "offline.r1Title": "\uBCF4\uB0B8 \uBA54\uC2DC\uC9C0\uB294 \uC804\uB2EC\uB429\uB2C8\uB2E4",
    "offline.r1Desc": "\uC624\uD504\uB77C\uC778\uC77C \uB54C \uC4F4 \uB0B4\uC6A9\uC740 \uC790\uB3D9\uC73C\uB85C \uC0C1\uB300\uC5D0\uAC8C \uC804\uC1A1\uB429\uB2C8\uB2E4.",
    "offline.r2Title": "\uD30C\uC77C \uC804\uC1A1\uC774 \uB9C8\uBB34\uB9AC\uB429\uB2C8\uB2E4",
    "offline.r2Desc": "\uC804\uC1A1\uC740 \uBA48\uCD98 \uC9C0\uC810\uBD80\uD130 \uC774\uC5B4\uC9D1\uB2C8\uB2E4 - \uB2E4\uC2DC \uBCF4\uB0BC \uD544\uC694\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4.",
    "offline.r3Title": "\uC0C1\uB300\uC758 \uBA54\uC2DC\uC9C0\uC640 \uD30C\uC77C\uC774 \uB3C4\uCC29\uD569\uB2C8\uB2E4",
    "offline.r3Desc": "\uB04A\uAE34 \uB3D9\uC548 \uC0C1\uB300\uAC00 \uBCF4\uB0B8 \uAC83\uB4E4\uC774 \uC21C\uC11C\uB300\uB85C \uB3C4\uCC29\uD569\uB2C8\uB2E4.",
    "offline.r4Title": "\uC544\uBB34\uAC83\uB3C4 \uC0AC\uB77C\uC9C0\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4",
    "offline.r4Desc": "\uB2E4\uC2DC \uC5F0\uACB0\uB418\uC5B4\uB3C4 \uBE48\uD2C8\uC740 \uC5C6\uC2B5\uB2C8\uB2E4 - \uB300\uD654\uB294 \uBA48\uCD98 \uADF8 \uC790\uB9AC\uC5D0\uC11C \uC774\uC5B4\uC9D1\uB2C8\uB2E4.",
