    "group.waitingJoin": "\uB2E4\uB978 \uAD6C\uC131\uC6D0\uC758 \uD569\uB958\uB97C \uAE30\uB2E4\uB9AC\uB294 \uC911\u2026",
    "group.emptyChat": "\uC544\uC9C1 \uC544\uBB34\uAC83\uB3C4 \uC5C6\uC2B5\uB2C8\uB2E4. \uBAA8\uB4E0 \uBA54\uC2DC\uC9C0\uB294 \uBCF4\uB0B8 \uC0AC\uB78C\uC774 \uC11C\uBA85\uD558\uBA70, \uAD6C\uC131\uC6D0 \uAC01\uC790\uC758 \uC554\uD638\uD654\uB41C \uD68C\uC120\uC744 \uD1B5\uD574 \uC624\uAC11\uB2C8\uB2E4.",
    "group.noVerified": "\uC544\uC9C1 \uD655\uC778\uB41C \uB300\uD654\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4. \uBA3C\uC800 1:1 \uB300\uD654\uB97C \uC5F4\uC5B4 \uC548\uC804 \uCF54\uB4DC\uB97C \uB300\uC870\uD558\uC138\uC694 - \uADF8\uB8F9\uC740 \uC774\uBBF8 \uD655\uC778\uD55C \uC5F0\uACB0\uB85C \uB9CC\uB4E4\uC5B4\uC9D1\uB2C8\uB2E4.",
    "group.noMoreToAdd": "\uCD94\uAC00\uD560 \uB2E4\uB978 \uD655\uC778\uB41C \uB300\uD654\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4. 1:1 \uB300\uD654\uB97C \uC5F4\uC5B4 \uBA3C\uC800 \uC548\uC804 \uCF54\uB4DC\uB97C \uB300\uC870\uD558\uC138\uC694.",
    "group.directLink": "\uAE30\uAE30 \uAC04 \uC9C1\uC811 \uC5F0\uACB0",
    "group.noDirectLink": "\uC544\uC9C1 \uC9C1\uC811 \uC5F0\uACB0\uC774 \uC5C6\uC2B5\uB2C8\uB2E4 - \uC5F0\uACB0\uC774 \uB9CC\uB4E4\uC5B4\uC9C0\uB294 \uB3D9\uC548 \uBA54\uC2DC\uC9C0\uB294 \uB2E4\uB978 \uAD6C\uC131\uC6D0\uC744 \uAC70\uCE69\uB2C8\uB2E4",
    "group.relayNote": "\uC77C\uBD80 \uAD6C\uC131\uC6D0\uACFC\uB294 \uC544\uC9C1 \uC9C1\uC811 \uC5F0\uACB0\uC774 \uC5C6\uC2B5\uB2C8\uB2E4. \uADF8\uB4E4\uC758 \uBA54\uC2DC\uC9C0\uB294 \uB2E4\uB978 \uAD6C\uC131\uC6D0\uC744 \uAC70\uCCD0 \uC624\uAC00\uB294\uB370, \uADF8 \uC0AC\uB78C\uC740 \uB300\uD654\uAC00 \uC624\uAC04\uB2E4\uB294 \uC0AC\uC2E4\uC740 \uC54C \uC218 \uC788\uC9C0\uB9CC \uC11C\uBA85 \uB108\uBA38\uC758 \uB0B4\uC6A9\uC744 \uC77D\uAC70\uB098 \uBC14\uAFC0 \uC218\uB294 \uC5C6\uC2B5\uB2C8\uB2E4. \uADF8\uB8F9\uC740 \uACC4\uC18D\uD574\uC11C \uC9C1\uC811 \uC5F0\uACB0\uC744 \uC2DC\uB3C4\uD569\uB2C8\uB2E4.",
    "group.relayOnlyOff": "\uB9B4\uB808\uC774 \uC804\uC6A9 \uBAA8\uB4DC\uAC00 \uAEBC\uC838 \uC788\uC5B4, \uBAA8\uB4E0 \uAD6C\uC131\uC6D0\uC774 \uC5EC\uB7EC\uBD84\uC5D0\uAC8C \uC9C1\uC811 \uC5F0\uACB0\uB418\uBA70 IP \uC8FC\uC18C\uB97C \uC54C\uAC8C \uB429\uB2C8\uB2E4 - \uB2E4\uB978 \uC0AC\uB78C\uC774 \uCD08\uB300\uD55C \uAD6C\uC131\uC6D0\uB3C4 \uB9C8\uCC2C\uAC00\uC9C0\uC785\uB2C8\uB2E4. \uADF8\uAC83\uC774 \uC911\uC694\uD558\uB2E4\uBA74 \uB124\uD2B8\uC6CC\uD06C \uC124\uC815\uC5D0\uC11C \uCF1C\uC138\uC694.",
    "group.memberOffline": "{name}\uB2D8\uC740 \uC624\uD504\uB77C\uC778\uC774\uB77C \uBA54\uC2DC\uC9C0\uB97C \uBC1B\uC9C0 \uBABB\uD569\uB2C8\uB2E4. \uC5EC\uC804\uD788 \uAD6C\uC131\uC6D0\uC774\uBA70, \uB0B4\uBCF4\uB0B4\uBA74 \uADF8\uB8F9 \uD0A4\uAC00 \uC0C8\uB85C \uB9CC\uB4E4\uC5B4\uC9D1\uB2C8\uB2E4.",
    "group.joinNote": "\uB2E4\uB978 \uAD6C\uC131\uC6D0\uB4E4\uC774 \uC5EC\uB7EC\uBD84\uC774 \uC774 \uADF8\uB8F9\uC5D0 \uC788\uB2E4\uB294 \uAC83\uC744 \uC54C\uAC8C \uB429\uB2C8\uB2E4. \uB530\uB77C\uC7A1\uC744 \uB300\uD654 \uAE30\uB85D\uC740 \uC5C6\uC2B5\uB2C8\uB2E4 - \uADF8\uB8F9\uC740 \uBE44\uC5B4 \uC788\uB294 \uC0C1\uD0DC\uB85C \uC2DC\uC791\uD569\uB2C8\uB2E4.",
    "group.inviteSentNote": "\uC0C1\uB300\uAC00 \uC218\uB77D\uD560 \uB54C\uAE4C\uC9C0 \uADF8\uB8F9\uC740 \uADF8\uB300\uB85C \uB3D9\uC791\uD569\uB2C8\uB2E4. \uADF8\uB4E4\uC774 \uB530\uB77C\uC7A1\uC744 \uAE30\uB85D\uC740 \uC5C6\uACE0, \uC9C0\uAE08\uBD80\uD130 \uBCF4\uB0B4\uB294 \uAC83\uB9CC \uBCF4\uAC8C \uB429\uB2C8\uB2E4.",
    "group.errNotCreated": "\uADF8\uB8F9\uC774 \uB9CC\uB4E4\uC5B4\uC9C0\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4",
    "group.errNobodyAccepted": "\uC81C\uB54C \uCD08\uB300\uB97C \uC218\uB77D\uD55C \uC0AC\uB78C\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.",
    "group.errNothingSent": "\uC544\uBB34\uAC83\uB3C4 \uC804\uC1A1\uB418\uAC70\uB098 \uD655\uC778\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uC774 \uCC3D\uC744 \uB2EB\uACE0 \uBAA8\uB450\uAC00 \uC5F0\uACB0\uB41C \uB4A4 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.",
    "group.errNotFormed": "\uC774 \uADF8\uB8F9\uC744 \uB9CC\uB4E4 \uC218 \uC5C6\uC5C8\uC2B5\uB2C8\uB2E4.",
    "group.errFull": "\uC774 \uADF8\uB8F9\uC740 \uAC00\uB4DD \uCC3C\uC2B5\uB2C8\uB2E4.",
    "group.errInviteFailed": "\uCD08\uB300\uB97C \uBCF4\uB0B4\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4 - \uADF8 \uB300\uD654\uB294 \uC5F0\uACB0\uB418\uC5B4 \uC788\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "group.errNoMemberList": "\uADF8\uB8F9\uC744 \uB9CC\uB4E0 \uC0AC\uB78C\uC774 \uAD6C\uC131\uC6D0 \uBA85\uB2E8\uC744 \uB05D\uB0B4 \uBCF4\uB0B4\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4.",
    "group.errUnsignedList": "\uAD6C\uC131\uC6D0 \uBA85\uB2E8\uC5D0 \uADF8\uB8F9\uC744 \uB9CC\uB4E0 \uC0AC\uB78C\uC758 \uC11C\uBA85\uC774 \uC5C6\uC2B5\uB2C8\uB2E4. \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC9C0 \uB9D0\uACE0 - \uADF8 \uC0AC\uB78C\uC5D0\uAC8C \uC54C\uB9AC\uC138\uC694.",
    "group.errNotOwner": "\uADF8\uB8F9 \uC18C\uC720\uC790\uAC00 \uC544\uB2CC \uB204\uAD70\uAC00\uAC00 \uAD6C\uC131\uC6D0\uC744 \uBC14\uAFB8\uB824 \uD588\uC2B5\uB2C8\uB2E4.",
