    "desktop.noChannelWait": "\uC5F4\uB9B0 \uBCF4\uC548 \uCC44\uB110\uC774 \uC5C6\uC2B5\uB2C8\uB2E4 - \uC5F0\uACB0\uC774 \uB9FA\uC5B4\uC9C8 \uB54C\uAE4C\uC9C0 \uAE30\uB2E4\uB9AC\uC138\uC694.",
    "desktop.sasFailed": "\uAC80\uC99D\uC5D0 \uC2E4\uD328\uD588\uC2B5\uB2C8\uB2E4. \uC911\uAC04\uC790\uAC00 \uC788\uC744 \uC218 \uC788\uC5B4 \uC5F0\uACB0\uC744 \uC911\uB2E8\uD588\uC2B5\uB2C8\uB2E4.",
    "desktop.sasOk": "\uAC80\uC99D\uC5D0 \uC131\uACF5\uD588\uC2B5\uB2C8\uB2E4. \uC774 \uCC44\uB110\uC740 \uC885\uB2E8 \uAC04 \uC778\uC99D\uB418\uC5C8\uC2B5\uB2C8\uB2E4.",
    "desktop.iceForgotten": "\uC800\uC7A5\uB41C \uC11C\uBC84\uB97C \uC9C0\uC6E0\uC2B5\uB2C8\uB2E4. \uACF5\uAC1C ICE \uC11C\uBC84\uB97C \uC0AC\uC6A9\uD569\uB2C8\uB2E4.",
    "desktop.icePublic": "\uACF5\uAC1C ICE \uC11C\uBC84\uB97C \uC0AC\uC6A9\uD569\uB2C8\uB2E4.",
    "desktop.verificationInProgress": "\uBCF4\uC548 \uAC80\uC99D\uC774 \uC544\uC9C1 \uC9C4\uD589 \uC911\uC785\uB2C8\uB2E4. \uB05D\uB0A0 \uB54C\uAE4C\uC9C0 \uAE30\uB2E4\uB9AC\uC138\uC694.",
    "desktop.fileGone": "\uC774 \uD30C\uC77C\uC740 \uB354 \uC774\uC0C1 \uB0B4\uB824\uBC1B\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.",
    "desktop.codeMismatch": "\uD655\uC778 \uCF54\uB4DC\uAC00 \uC77C\uCE58\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC548\uC804\uC744 \uC704\uD574 \uC5F0\uACB0\uC744 \uB04A\uC2B5\uB2C8\uB2E4.",
    "desktop.noLocalCode": "\uAC80\uC99D \uC2E4\uD328: \uBE44\uAD50\uD560 \uB85C\uCEEC \uD30C\uC0DD \uCF54\uB4DC\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4. \uC548\uC804\uC744 \uC704\uD574 \uC5F0\uACB0\uC744 \uB04A\uC2B5\uB2C8\uB2E4.",
    "desktop.protocolViolation": "\uC0C1\uB300\uAC00 \uB2F9\uC2E0\uC774 \uD655\uC778\uD558\uAE30 \uC804\uC5D0 \uCF54\uB4DC\uAC00 \uD655\uC778\uB418\uC5C8\uB2E4\uACE0 \uC8FC\uC7A5\uD588\uC2B5\uB2C8\uB2E4. \uC548\uC804\uC744 \uC704\uD574 \uC5F0\uACB0\uC744 \uB04A\uC2B5\uB2C8\uB2E4.",
