    "status.verifying": "\u0938\u0924\u094D\u092F\u093E\u092A\u0928 \u091C\u093E\u0930\u0940\u2026",
    "status.peerDisconnected": "\u0938\u093E\u092E\u0928\u0947 \u0935\u093E\u0932\u0947 \u0915\u093E \u091C\u0941\u0921\u093C\u093E\u0935 \u091F\u0942\u091F\u093E",
    "sec.replayProtection": "\u092A\u0941\u0928\u0930\u093E\u0935\u0943\u0924\u094D\u0924\u093F \u0939\u092E\u0932\u0947 \u0938\u0947 \u092C\u091A\u093E\u0935",
    "sec.messageIntegrity": "\u0938\u0902\u0926\u0947\u0936 \u0915\u0940 \u0905\u0916\u0902\u0921\u0924\u093E (HMAC)",
    "sec.forwardSecrecy": "\u092A\u0942\u0930\u094D\u0923 \u0905\u0917\u094D\u0930\u0917\u093E\u092E\u0940 \u0917\u094B\u092A\u0928\u0940\u092F\u0924\u093E",
    "sec.metadataProtection": "\u092E\u0947\u091F\u093E\u0921\u0947\u091F\u093E \u0938\u0941\u0930\u0915\u094D\u0937\u093E",
    "sec.trafficObfuscation": "\u091F\u094D\u0930\u0948\u092B\u093C\u093F\u0915 \u0905\u0938\u094D\u092A\u0937\u094D\u091F\u0940\u0915\u0930\u0923",
    "sec.realTests": "\u0905\u0938\u0932\u0940 \u0915\u094D\u0930\u093F\u092A\u094D\u091F\u094B\u0917\u094D\u0930\u093E\u092B\u093C\u093F\u0915 \u091C\u093E\u0901\u091A\u0947\u0902",
    "sec.simulatedData": "\u092C\u0928\u093E\u0935\u091F\u0940 \u0921\u0947\u091F\u093E",
    "sec.testPassed": "\u091C\u093E\u0901\u091A \u092A\u093E\u0938",
    "sec.testFailed": "\u091C\u093E\u0901\u091A \u0935\u093F\u092B\u0932 \u092F\u093E \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902",
    "sec.verificationDone": "\u0905\u0938\u0932\u0940 \u0915\u094D\u0930\u093F\u092A\u094D\u091F\u094B\u0917\u094D\u0930\u093E\u092B\u093C\u093F\u0915 \u0938\u0924\u094D\u092F\u093E\u092A\u0928 \u092A\u0942\u0930\u093E \u0939\u0941\u0906",
    "sec.verificationInProgress": "\u0938\u0941\u0930\u0915\u094D\u0937\u093E \u0938\u0924\u094D\u092F\u093E\u092A\u0928 \u091C\u093E\u0930\u0940\u2026",
    "sec.verificationWait": "\u0938\u0941\u0930\u0915\u094D\u0937\u093E \u0938\u0924\u094D\u092F\u093E\u092A\u0928 \u091C\u093E\u0930\u0940\u2026\n\u0915\u0943\u092A\u092F\u093E \u0935\u093E\u0938\u094D\u0924\u0935\u093F\u0915 \u0938\u092E\u092F \u0915\u0940 \u0915\u094D\u0930\u093F\u092A\u094D\u091F\u094B\u0917\u094D\u0930\u093E\u092B\u093C\u093F\u0915 \u091C\u093E\u0901\u091A \u092A\u0942\u0930\u0940 \u0939\u094B\u0928\u0947 \u0924\u0915 \u0930\u0941\u0915\u093F\u090F\u0964",
    "sec.verificationUnavailable": "\u0938\u0941\u0930\u0915\u094D\u0937\u093E \u0938\u0924\u094D\u092F\u093E\u092A\u0928 \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902",
    "chat.placeholder": "\u090F\u0928\u094D\u0915\u094D\u0930\u093F\u092A\u094D\u091F\u0947\u0921 \u0938\u0902\u0926\u0947\u0936 \u0932\u093F\u0916\u0947\u0902\u2026",
