    "chat.hideFiles": "\u092B\u093C\u093E\u0907\u0932\u0947\u0902 \u091B\u093F\u092A\u093E\u090F\u0901",
    "chat.recordVoice": "\u0935\u0949\u0907\u0938 \u0938\u0902\u0926\u0947\u0936 \u0930\u093F\u0915\u0949\u0930\u094D\u0921 \u0915\u0930\u0947\u0902",
    "chat.sendVoice": "\u0935\u0949\u0907\u0938 \u0938\u0902\u0926\u0947\u0936 \u092D\u0947\u091C\u0947\u0902",
    "chat.discard": "\u091B\u094B\u0921\u093C\u0947\u0902",
    "chat.codeBlock": "\u0915\u094B\u0921 \u092C\u094D\u0932\u0949\u0915 \u0915\u0947 \u0930\u0942\u092A \u092E\u0947\u0902 \u092D\u0947\u091C\u0947\u0902 (\u0907\u0928\u092A\u0941\u091F \u092C\u0921\u093C\u093E \u0939\u094B \u091C\u093E\u090F\u0917\u093E)",
    "chat.codeHint": "\u0915\u094B\u0921 \u0915\u093E \u0905\u0902\u0936 \xB7 \u0930\u0942\u092A-\u0938\u091C\u094D\u091C\u093E \u092C\u0928\u0940 \u0930\u0939\u0947\u0917\u0940 \xB7 \u092D\u0947\u091C\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u2318\u21B5",
