    "chat.delivered": "\u092A\u0939\u0941\u0901\u091A \u0917\u092F\u093E",
    "chat.notSent": "\u0928\u0939\u0940\u0902 \u092D\u0947\u091C\u093E \u0917\u092F\u093E",
