    "err.needResponse": "\u0938\u093E\u092E\u0928\u0947 \u0935\u093E\u0932\u0947 \u0915\u093E \u0926\u093F\u092F\u093E \u0909\u0924\u094D\u0924\u0930 \u0915\u094B\u0921 \u091A\u093F\u092A\u0915\u093E\u0928\u093E \u091C\u093C\u0930\u0942\u0930\u0940 \u0939\u0948\u0964",
    "err.responseFormat": "\u0909\u0924\u094D\u0924\u0930 \u0915\u093E \u092A\u094D\u0930\u093E\u0930\u0942\u092A \u0917\u093C\u0932\u0924 \u0939\u0948 - \u0915\u094B\u0921 \u091C\u093E\u0901\u091A\u093F\u090F",
    "err.responseNoKey": "\u0909\u0924\u094D\u0924\u0930 \u0915\u094B\u0921 \u0917\u093C\u0932\u0924 \u0939\u0948 - \u0915\u094D\u0930\u093F\u092A\u094D\u091F\u094B\u0917\u094D\u0930\u093E\u092B\u093C\u093F\u0915 \u0915\u0941\u0902\u091C\u0940 \u0928\u0939\u0940\u0902 \u0939\u0948 \u092F\u093E \u0916\u093C\u0930\u093E\u092C \u0939\u0948\u0964 \u0915\u094B\u0921 \u091C\u093E\u0901\u091A\u0915\u0930 \u0926\u094B\u092C\u093E\u0930\u093E \u0915\u094B\u0936\u093F\u0936 \u0915\u0940\u091C\u093F\u090F\u0964",
    "err.responseNoSignKey": "\u0909\u0924\u094D\u0924\u0930 \u0915\u094B\u0921 \u0917\u093C\u0932\u0924 \u0939\u0948 - \u0939\u0938\u094D\u0924\u093E\u0915\u094D\u0937\u0930 \u091C\u093E\u0901\u091A\u0928\u0947 \u0915\u0940 \u0915\u0941\u0902\u091C\u0940 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u0915\u094B\u0921 \u091C\u093E\u0901\u091A\u0915\u0930 \u0926\u094B\u092C\u093E\u0930\u093E \u0915\u094B\u0936\u093F\u0936 \u0915\u0940\u091C\u093F\u090F\u0964",
    "err.responseOutdated": "\u0909\u0924\u094D\u0924\u0930 \u0915\u093E \u0921\u0947\u091F\u093E \u092A\u0941\u0930\u093E\u0928\u093E \u0939\u0948 - \u0928\u092F\u093E \u0928\u093F\u092E\u0902\u0924\u094D\u0930\u0923 \u0907\u0938\u094D\u0924\u0947\u092E\u093E\u0932 \u0915\u0940\u091C\u093F\u090F",
