    "pwa.installedIos": "\u05D0\u05E4\u05DC\u05D9\u05E7\u05E6\u05D9\u05D9\u05EA iOS \u05D4\u05D5\u05EA\u05E7\u05E0\u05D4! \u05E4\u05EA\u05D7\u05D5 \u05DE\u05DE\u05E1\u05DA \u05D4\u05D1\u05D9\u05EA.",
