    "desktop.sec.metadataNone": "\u06A9\u0644\u06CC\u062F \u0641\u0631\u0627\u062F\u0627\u062F\u0647 \u0648\u062C\u0648\u062F \u0646\u062F\u0627\u0631\u062F",
