    "qr.showSubtitle": "\u067E\u0648\u0631\u06CC \u0633\u06A9\u0631\u06CC\u0646 \xB7 \u0633\u0627\u062A\u06BE\u06CC \u06A9\u0648 \u067E\u0691\u06BE\u0646\u06D2 \u062F\u06CC\u06BA",
