    "sec.realTests": "\u062D\u0642\u06CC\u0642\u06CC \u062E\u0641\u06CC\u06C1 \u0646\u06AF\u0627\u0631\u06CC \u06A9\u06D2 \u062A\u062C\u0631\u0628\u0627\u062A",
